function solve(linha) {
  const result = [];
  let i = 0;
  let current = '';
  let inQuotes = false;

  while (i < linha.length) {
    const ch = linha[i];

    if (ch === '"') {
      if (inQuotes && i + 1 < linha.length && linha[i + 1] === '"') {
        // Escaped quote ""
        current += '"';
        i += 2;
      } else {
        // Toggle quote state
        inQuotes = !inQuotes;
        i++;
      }
    } else if (ch === ',' && !inQuotes) {
      // Comma outside quotes → field separator
      result.push(current);
      current = '';
      i++;
    } else {
      current += ch;
      i++;
    }
  }

  // Push the last field
  result.push(current);

  return result;
}
