function solve(a, b) {
  const parse = (version) => {
    // Remove build metadata (per SemVer 2.0.0 spec)
    version = version.split('+')[0].trim();

    const parts = version.split('.');
    const major = parseInt(parts[0], 10);
    const minor = parseInt(parts[1], 10);
    const patch = parseInt(parts[2], 10);

    // Pre-release: everything after the 3rd dot
    const preReleaseStr = parts.slice(3).join('.');
    const preRelease = preReleaseStr ? preReleaseStr.split('-') : [];

    return { major, minor, patch, preRelease };
  };

  const aParsed = parse(a);
  const bParsed = parse(b);

  // Major.minor.patch comparison
  if (aParsed.major !== bParsed.major) return aParsed.major < bParsed.major ? -1 : 1;
  if (aParsed.minor !== bParsed.minor) return aParsed.minor < bParsed.minor ? -1 : 1;
  if (aParsed.patch !== bParsed.patch) return aParsed.patch < bParsed.patch ? -1 : 1;

  // Pre-release: a pre-release is always lower than a release
  if (aParsed.preRelease.length > 0 && bParsed.preRelease.length === 0) return -1;
  if (aParsed.preRelease.length === 0 && bParsed.preRelease.length > 0) return 1;

  // Compare pre-release labels one by one
  const len = Math.min(aParsed.preRelease.length, bParsed.preRelease.length);
  for (let i = 0; i < len; i++) {
    const aId = aParsed.preRelease[i];
    const bId = bParsed.preRelease[i];

    const aIsNumeric = /^\d+$/.test(aId);
    const bIsNumeric = /^\d+$/.test(bId);

    if (aIsNumeric && bIsNumeric) {
      const aNum = parseInt(aId, 10);
      const bNum = parseInt(bId, 10);
      if (aNum !== bNum) return aNum < bNum ? -1 : 1;
    } else if (aIsNumeric && !bIsNumeric) {
      return -1; // numeric < non-numeric
    } else if (!aIsNumeric && bIsNumeric) {
      return 1; // non-numeric > numeric
    } else {
      // Both non-numeric: compare lexicographically
      if (aId < bId) return -1;
      if (aId > bId) return 1;
    }
  }

  // Same number of labels but one is shorter
  if (aParsed.preRelease.length < bParsed.preRelease.length) return -1;
  if (aParsed.preRelease.length > bParsed.preRelease.length) return 1;

  return 0;
}
