  function parse(v) {
    const parts = v.split('-');
    const core = parts[0].split('.').map(Number);
    const prerelease = parts.length > 1 ? parts[1].split('.').filter(Boolean) : [];
    return { core, prerelease };
  }

  const aParts = parse(a);
  const bParts = parse(b);

  for (let i = 0; i < 3; i++) {
    if (aParts.core[i] !== bParts.core[i]) {
      return aParts.core[i] > bParts.core[i] ? 1 : -1;
    }
  }

  const aPre = aParts.prerelease;
  const bPre = bParts.prerelease;

  if (aPre.length === 0 && bPre.length === 0) return 0;
  if (aPre.length === 0) return 1;
  if (bPre.length === 0) return -1;

  const len = Math.min(aPre.length, bPre.length);
  for (let i = 0; i < len; i++) {
    const ai = aPre[i], bi = bPre[i];
    const aNum = Number(ai);
    const bNum = Number(bi);
    if (!isNaN(aNum) && !isNaN(bNum)) {
      if (aNum !== bNum) return aNum > bNum ? 1 : -1;
    } else {
      if (ai !== bi) return ai < bi ? -1 : 1;
    }
  }

