function solve(expr) {
  let i = 0;

  function skipSpaces() {
    while (i < expr.length && expr[i] === ' ') i++;
  }

  function parseExpr() {
    skipSpaces();
    let result = parseTerm();
    while (i < expr.length && expr[i] !== ')' && expr[i] !== undefined) {
      skipSpaces();
      const op = expr[i];
      if (op === '+' || op === '-') {
        i++;
        skipSpaces();
        const right = parseTerm();
        result = op === '+' ? result + right : result - right;
      } else {
        break;
      }
    }
    return result;
  }

  function parseTerm() {
    skipSpaces();
    let result = parseFactor();
    while (i < expr.length && expr[i] !== ')' && expr[i] !== undefined) {
      skipSpaces();
      const op = expr[i];
      if (op === '*' || op === '/') {
        i++;
        skipSpaces();
        const right = parseFactor();
        result = op === '*' ? result * right : result / right;
      } else {
        break;
      }
    }
    return result;
  }

  function parseFactor() {
    skipSpaces();
    if (i >= expr.length) return 0;
    if (expr[i] === '(') {
      i++;
      const result = parseExpr();
      skipSpaces();
      if (i < expr.length && expr[i] === ')') i++;
      return result;
    }
    if (expr[i] === '-' || expr[i] === '+') {
      const sign = expr[i] === '-' ? -1 : 1;
      i++;
      skipSpaces();
      return sign * parseFactor();
    }
    return parseNumber();
  }

  function parseNumber() {
    skipSpaces();
    let num = '';
    while (i < expr.length && /[\d]/.test(expr[i])) {
      num += expr[i];
      i++;
    }
    return parseInt(num, 10);
  }

  return parseExpr();
}
