function solve(intervalos) {
  if (!intervalos.length) return [];

  // Ordena por início
  const sorted = intervalos.slice().sort((a, b) => a[0] - b[0]);

  const merged = [sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const [inicioAtual, fimAtual] = merged[merged.length - 1];
    const [inicioNovo, fimNovo] = sorted[i];

    if (inicioNovo <= fimAtual) {
      // Há sobreposição ou toque — mescla
      merged[merged.length - 1] = [
        Math.min(inicioAtual, inicioNovo),
        Math.max(fimAtual, fimNovo)
      ];
    } else {
      merged.push(sorted[i]);
    }
  }

  return merged;
}
