function solve(s) {
  let i = 0;
  const n = s.length;

  // Ignora espaços iniciais
  while (i < n && s[i] === ' ') i++;

  // Sinal opcional
  let sign = 1;
  if (i < n && s[i] === '+') {
    i++;
  } else if (i < n && s[i] === '-') {
    sign = -1;
    i++;
  }

  // Lê dígitos
  let num = 0;
  while (i < n && s[i] >= '0' && s[i] <= '9') {
    const d = parseInt(s[i], 10);
    // Verificação de overflow antes de multiplicar
    if (num > 214748364) {
      return sign === 1 ? 2147483647 : -2147483648;
    }
    num = num * 10 + d;
    i++;
  }

  if (i === 0) return 0;

  num *= sign;

  // Limitação para 32 bits sinalizado
  if (num < -2147483648) num = -2147483648;
  if (num > 2147483647) num = 2147483647;

  return num;
}
