  const n = s.length;

  // Ignore leading spaces
  while (i < n && s[i] === ' ') i++;

  if (i >= n) return 0;

  let sign = 1;
  if (s[i] === '+') {
    sign = 1;
    i++;
  } else if (s[i] === '-') {
    sign = -1;
    i++;
  }

  let result = 0;
  while (i < n && s[i] >= '0' && s[i] <= '9') {
    const digit = s[i] - '0';
    // Check for overflow before it happens
    if (result > (Math.pow(2, 31) - 1 - digit) / 10) {
      return sign === 1 ? Math.pow(2, 31) - 1 : -Math.pow(2, 31);
    }
    result = result * 10 + digit;
    i++;
  }

  return result * sign;
}
