function solve(precos) {
  const n = precos.length;
  if (n <= 1) return 0;

  // max_profit_up_to[i]: lucro máximo com no máximo 1 transação em [0..i]
  const max_profit_up_to = new Array(n);
  let min = precos[0], profit = 0;
  for (let i = 0; i < n; i++) {
    min = Math.min(min, precos[i]);
    profit = Math.max(profit, precos[i] - min);
    max_profit_up_to[i] = profit;
  }

  // max_profit_from[i]: lucro máximo com no máximo 1 transação em [i..n-1]
  const max_profit_from = new Array(n);
  let max = precos[n - 1], profit = 0;
  for (let i = n - 1; i >= 0; i--) {
    max = Math.max(max, precos[i]);
    profit = Math.max(profit, max - precos[i]);
    max_profit_from[i] = profit;
  }

  let max_profit = max_profit_up_to[n - 1];
  for (let i = 0; i < n - 1; i++) {
    max_profit = Math.max(max_profit, max_profit_up_to[i] + max_profit_from[i + 1]);
  }
  return max_profit;
}
