function solve(s) {
  if (typeof s !== 'string') return s;

  // Usa a API Intl.Segmenter para segmentar corretamente por grafemas (usuário vê)
  // Isso lida com emojis compostos, bandeiras, letras com acento, etc.
  const segmenter = new Intl.Segmenter('en', { granularity: 'grapheme' });
  const segments = [...segmenter.segment(s)];

  // Extrai os grafemas, inverte a ordem e junta
  const graphemes = segments.map(seg => seg.segment);
  return graphemes.reverse().join('');
}
