  if (pa.prerelease === pb.prerelease) return 0;

  // One has prerelease, the other doesn't
  if (pa.prerelease === null) return 1; // a has prerelease, b does not → a > b (a is newer)
  if (pb.prerelease === null) return -1; // b has prerelease, a does not → a < b

  // Both have prerelease: compare identifiers
