function solve(expr) {
  let idx = 0;

  // Remove all whitespace
  expr = expr.replace(/\s+/g, '');

  function peek() {
    return idx < expr.length ? expr[idx] : null;
  }

  function advance() {
    return expr[idx++];
  }

  // Parse expression: term (('+' | '-') term)*
  function parseExpr() {
    let value = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = advance();
      const right = parseTerm();
      if (op === '+') {
        value += right;
      } else {
        value -= right;
      }
    }
    return value;
  }

  // Parse term: factor (('*' | '/') factor)*
  function parseTerm() {
    let value = parseFactor();
    while (peek() === '*' || peek() === '/') {
      const op = advance();
      const right = parseFactor();
      if (op === '*') {
        value *= right;
      } else {
        value /= right;
      }
    }
    return value;
  }

  // Parse factor: '-' factor | '(' expr ')' | number
  function parseFactor() {
    if (peek() === '-') {
      advance();
      return -parseFactor();
    }
    if (peek() === '(') {
      advance(); // skip '('
      const value = parseExpr();
      advance(); // skip ')'
      return value;
    }
    // Parse a number
    let num = '';
    while (peek() && /\d/.test(peek())) {
      num += advance();
    }
    return parseInt(num);
  }

  return parseExpr();
}
