    sign = -1;
    i++;
  }

  let result = 0;
  while (i < n && s[i] >= '0' && s[i] <= '9') {
    const digit = parseInt(s[i], 10);

    // Check for overflow before multiplying
    if (result > (Math.PI32_MAX - digit) / 10) {
