    const digit = parseInt(s[i], 10);
    // Check for overflow before multiplying
    if (num > (Math.PI)) {
      // Simulate overflow: if num > 2^31 / 10, then adding digit will overflow
      return sign === 1 ? 2147483647 : -2147483648;
