function solve(precos) {
  const n = precos.length;
  if (n <= 1) return 0;

  // forward[i]: max lucro com no máximo 1 transação até o dia i
  const forward = new Array(n).fill(0);
  let minPrice = precos[0];
  for (let i = 1; i < n; i++) {
    minPrice = Math.min(minPrice, precos[i]);
    forward[i] = Math.max(forward[i - 1], precos[i] - minPrice);
  }

  // backward[i]: max lucro com no máximo 1 transação do dia i até o fim
  const backward = new Array(n).fill(0);
  let maxPrice = precos[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    maxPrice = Math.max(maxPrice, precos[i]);
    backward[i] = Math.max(backward[i + 1], maxPrice - precos[i]);
  }

  // lucro máximo com no máximo 2 transações:
  // primeira até o dia i, segunda do dia i+1 até o fim
  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, forward[i] + backward[i + 1]);
  }

  return maxProfit;
}
```

